import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Security headers.
  //
  // These live here, not in netlify.toml: Netlify's [[headers]] only apply to
  // files its CDN serves directly (/_next/static/*), NOT to HTML generated by
  // the Next.js runtime — which is every page on this site, and exactly where
  // clickjacking and referrer protections matter. Verified in production:
  // the netlify.toml block reached a .css asset and reached no page at all.
  // The netlify.toml block is kept as well, for assets served without
  // involving the Next runtime.
  //
  // No Content-Security-Policy yet, deliberately: with GA4, Sanity's CDN and
  // an embedded Studio, a CSP must be built against real traffic in
  // report-only mode. A wrong CSP fails silently for visitors.
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          // SAMEORIGIN, not DENY: Sanity's Presentation tool iframes the site
          // from /studio, which is the same origin here.
          { key: "X-Frame-Options", value: "SAMEORIGIN" },
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
          {
            key: "Permissions-Policy",
            value: "camera=(), microphone=(), geolocation=(), interest-cohort=()",
          },
        ],
      },
    ];
  },
  experimental: {
    // Two root layouts ((site) and (studio)) mean there is no single layout
    // to build a global 404 from — the case Next documents
    // global-not-found.tsx for. See node_modules/next/dist/docs/01-app/
    // 03-api-reference/03-file-conventions/not-found.md.
    globalNotFound: true,
  },
  reactCompiler: true,
  images: {
    // Blog hero/card images (app/(site)/blog/page.tsx) are served from
    // Sanity's asset CDN and passed straight into next/image. Without an
    // explicit allow-list next/image rejects any remote `src` with a 400,
    // so every blog image breaks. Scoped narrowly to cdn.sanity.io over
    // https only — do not widen this to a wildcard hostname.
    remotePatterns: [
      {
        protocol: "https",
        hostname: "cdn.sanity.io",
      },
    ],
  },
};

export default nextConfig;
